#pragma once

// Apple GPUs have no FP64, and double-precision HLSL breaks the Metal
// compiler. This rewrites code generated by the MDL SDK's HLSL backend to
// single precision, as the SDK's (unreleased) hlsl_disable_double option does:
//   - the types double, doubleN and doubleNxM become float, floatN, floatNxM,
//   - the l/L suffix of floating-point literals is dropped,
// with identifiers such as mdl_read_argblock_as_double left untouched. Code
// that still names the double type afterwards is rejected, so a new SDK
// construct fails with a clear error instead of reaching the converter.

#include <string>

namespace prism::device::gpu {

bool RewriteHlslToFp32(std::string const& code, std::string* result, std::string* error);

} // namespace prism::device::gpu
